const KEY = 'd2m.changelogSeen';

/** Date de la dernière entrée vue (ou '' si jamais ouvert) */
function changelogSeen(): string {
  try {
    return localStorage.getItem(KEY) ?? '';
  } catch {
    return '';
  }
}

export function markChangelogSeen(): void {
  try {
    localStorage.setItem(KEY, CHANGELOG[0]?.date ?? '');
  } catch {
    /* sans stockage : le point de nouveauté reste affiché */
  }
}

/** Nombre d'entrées plus récentes que la dernière vue */
export function unseenChanges(): number {
  const seen = changelogSeen();
  return CHANGELOG.filter((e) => e.date > seen).length;
}
